import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    T = int(input_data[1])

    if T == 0:
        ans = N
    elif T == 1:
        ans = N * (N - 1)
    else: # T == 2
        ans = N * (N - 1) * (N - 2) // 6

    print(ans)

if __name__ == '__main__':
    main()
